import * as React from "react";
type DialogContextValue = { open: boolean; setOpen: (open: boolean) => void };
const DialogContext = React.createContext<DialogContextValue | null>(null);
export type DialogProps = { open?: boolean; defaultOpen?: boolean; onOpenChange?: (open: boolean) => void; children?: React.ReactNode };
export function Dialog({ open: controlled, defaultOpen = false, onOpenChange, children }: DialogProps) { const [internal,setInternal]=React.useState(defaultOpen); const open=controlled??internal; const setOpen=(next:boolean)=>{if(controlled===undefined)setInternal(next);onOpenChange?.(next)}; return <DialogContext.Provider value={{open,setOpen}}>{children}</DialogContext.Provider>; }
export function DialogTrigger({ className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) { const ctx=React.useContext(DialogContext); return <button type="button" className={className} onClick={(event)=>{ctx?.setOpen(true);props.onClick?.(event)}} {...props} />; }
export function DialogPortal({ children }: { children?: React.ReactNode }) { return <>{children}</>; }
export function DialogOverlay({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) { const ctx=React.useContext(DialogContext); if(!ctx?.open)return null; return <div aria-hidden className={["fixed inset-0 z-40 bg-black/60 backdrop-blur-sm",className].filter(Boolean).join(" ")} onClick={()=>ctx.setOpen(false)} {...props} />; }
export const DialogContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function DialogContent({ className, ...props }, ref) { const ctx=React.useContext(DialogContext); if(!ctx?.open)return null; return <div ref={ref} role="dialog" aria-modal="true" className={["fixed left-1/2 top-1/2 z-50 w-full max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-xl border border-border bg-card text-card-foreground shadow-xl",className].filter(Boolean).join(" ")} {...props} />; });
DialogContent.displayName="DialogContent";
export function DialogClose({ className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) { const ctx=React.useContext(DialogContext); return <button type="button" className={className} onClick={(event)=>{ctx?.setOpen(false);props.onClick?.(event)}} {...props} />; }
export const DialogHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function DialogHeader({ className, ...props }, ref) { return <div ref={ref} className={["flex flex-col space-y-1.5 text-center sm:text-left",className].filter(Boolean).join(" ")} {...props} />; });
export const DialogFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(function DialogFooter({ className, ...props }, ref) { return <div ref={ref} className={["flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2",className].filter(Boolean).join(" ")} {...props} />; });
export const DialogTitle = React.forwardRef<HTMLHeadingElement, React.HTMLAttributes<HTMLHeadingElement>>(function DialogTitle({ className, ...props }, ref) { return <h2 ref={ref} className={["text-lg font-semibold",className].filter(Boolean).join(" ")} {...props} />; });
export const DialogDescription = React.forwardRef<HTMLParagraphElement, React.HTMLAttributes<HTMLParagraphElement>>(function DialogDescription({ className, ...props }, ref) { return <p ref={ref} className={["text-sm text-muted-foreground",className].filter(Boolean).join(" ")} {...props} />; });
